    outcomes: [
      { endpoint: "Event-free survival (median)", primary: true, unit: "months", arms: [{ name: "Axi-cel", n: 180, value: 8.3 }, { name: "Standard care", n: 179, value: 2.0 }], hr: 0.40, ci: [0.31, 0.51], p: "<0.001", source: "https://www.nejm.org/doi/full/10.1056/NEJMoa2116133" },
      { endpoint: "Overall survival at 4 years", unit: "%", arms: [{ name: "Axi-cel", value: 54.6 }, { name: "Standard care", value: 46.0 }], hr: 0.73, ci: [0.54, 0.98], p: "0.03", source: "https://www.nejm.org/doi/full/10.1056/NEJMoa2301665" },
    ],
